func run(args []string) int {
    var excludes multiFlag
    fs := flag.NewFlagSet(args[0], flag.ContinueOnError)
    fs.SetOutput(os.Stderr)
    configPath := fs.String("config", "", "path to the configuration TOML file, defaults to $XDG_CONFIG_HOME/revive.toml or $HOME/revive.toml, if present (i.e. -config myconf.toml)")
    fs.Var(&excludes, "exclude", "list of globs which specify files to be excluded (i.e. -exclude foo/...)")
    formatter := fs.String("formatter", "", "formatter to be used for the output (i.e. -formatter stylish)")
    fs.Int("max_open_files", 0, "maximum number of open files at the same time")
    setExit := fs.Bool("set_exit_status", false, "set exit status to 1 if any issues are found, overwrites errorCode and warningCode in config")
    version := fs.Bool("version", false, "get revive version")
    fs.Usage = func() {
        fmt.Fprint(os.Stdout, logo)
        fmt.Fprintf(os.Stderr, "Usage of %s:\n", args[0])
        fs.PrintDefaults()
    }
    if err := fs.Parse(args[1:]); err != nil {
        return 2
    }
    if *version {
        fmt.Fprint(os.Stdout, versionText)
        return 0
    }
    if *formatter == "" {
        *formatter = "default"
    }
    if !isFormatter(*formatter) {
        fmt.Fprintf(os.Stderr, "formatting - getting formatter: unknown formatter %s\n", *formatter)
        return 1
    }

    cfg, err := loadConfig(*configPath)
    if err != nil {
        fmt.Fprintln(os.Stderr, err.Error())
        return 1
    }
    files, err := collectFiles(fs.Args(), []string(excludes))
    if err != nil {
        fmt.Fprintln(os.Stderr, err.Error())
        return 1
    }
    failures := lintFiles(files, cfg)
    applyDirectivesAndConfig(&failures, cfg)
    sortFailures(failures)
    formatFailures(*formatter, failures)

    if len(failures) > 0 {
        if *setExit { return 1 }
        hasErr, hasWarn := false, false
        for _, f := range failures {
            if f.Severity == "error" { hasErr = true } else { hasWarn = true }
        }
        if hasErr && cfg.ErrorCode != 0 { return cfg.ErrorCode }
        if hasWarn && cfg.WarningCode != 0 { return cfg.WarningCode }
    }
    return 0
}

func isFormatter(s string) bool {
    switch s {
    case "default", "json", "ndjson", "friendly", "stylish", "checkstyle", "sarif", "plain", "unix":
        return true
    }
    return false
}

func defaultConfig() Config {
    return Config{Severity: "warning", RuleConfigs: map[string]*RuleConfig{}, EnabledRules: append([]string(nil), defaultRules...)}
}

func loadConfig(path string) (Config, error) {
    if path == "" {
        if xdg := os.Getenv("XDG_CONFIG_HOME"); xdg != "" {
            p := filepath.Join(xdg, "revive.toml")
            if _, err := os.Stat(p); err == nil { path = p }
        }
        if path == "" {
            if home := os.Getenv("HOME"); home != "" {
                p := filepath.Join(home, "revive.toml")
                if _, err := os.Stat(p); err == nil { path = p }
            }
        }
        if path == "" { return defaultConfig(), nil }
    }
    data, err := os.ReadFile(path)
    if err != nil { return Config{}, errors.New("cannot read the config file") }
    cfg := Config{FromFile: true, Severity: "warning", RuleConfigs: map[string]*RuleConfig{}}
    current := ""
    lines := strings.Split(string(data), "\n")
    for i, raw := range lines {
        line := strings.TrimSpace(stripComment(raw))
        if line == "" { continue }
        if strings.HasPrefix(line, "[") {
            if !strings.HasSuffix(line, "]") {
                return Config{}, fmt.Errorf("cannot parse the config file: toml: line %d: expected '.' or ']' to end table name", i+1)
            }
            sec := strings.TrimSpace(line[1:len(line)-1])
            current = sec
            if strings.HasPrefix(sec, "rule.") {
                name := strings.Trim(strings.TrimPrefix(sec, "rule."), "\"")
                if cfg.RuleConfigs[name] == nil { cfg.RuleConfigs[name] = &RuleConfig{Name: name} }
            }
            continue
        }
        parts := strings.SplitN(line, "=", 2)
        if len(parts) != 2 { continue }
        key := strings.TrimSpace(parts[0])
        val := strings.TrimSpace(parts[1])
        if strings.HasPrefix(current, "rule.") {
            name := strings.Trim(strings.TrimPrefix(current, "rule."), "\"")
            rc := cfg.RuleConfigs[name]
            if rc == nil { rc = &RuleConfig{Name: name}; cfg.RuleConfigs[name] = rc }
            switch strings.ToLower(key) {
            case "disabled":
                rc.Disabled = strings.EqualFold(val, "true")
            case "severity":
                rc.Severity = parseString(val)
            case "arguments":
                rc.Arguments = parseArray(val)
            }
        } else {
            switch key {
            case "severity":
                cfg.Severity = parseString(val)
            case "confidence":
                if f, err := strconv.ParseFloat(strings.Trim(val, "\""), 64); err == nil { cfg.Confidence = f }
            case "errorCode":
                if n, err := strconv.Atoi(strings.Trim(val, "\"")); err == nil { cfg.ErrorCode = n }
            case "warningCode":
                if n, err := strconv.Atoi(strings.Trim(val, "\"")); err == nil { cfg.WarningCode = n }
            }
        }
    }
    names := make([]string, 0, len(cfg.RuleConfigs))
    for name, rc := range cfg.RuleConfigs {
        if !knownRules[name] && !rc.Disabled {
            return Config{}, fmt.Errorf("initializing revive - getting lint rules: cannot find rule: %s", name)
        }
        if name == "line-length-limit" && !rc.Disabled && len(rc.Arguments) > 0 {
            if _, err := strconv.Atoi(strings.Trim(rc.Arguments[0], "\"")); err != nil {
                return Config{}, errors.New("initializing revive - getting lint rules: cannot configure rule: \"line-length-limit\": invalid value passed as argument number to the \"line-length-limit\" rule")
            }
        }
        if !rc.Disabled { names = append(names, name) }
    }
    sort.Strings(names)
    cfg.EnabledRules = names
    return cfg, nil
}

func stripComment(s string) string {
    in := false
    esc := false
    for i, r := range s {
        if r == '\\' && in { esc = !esc; continue }
        if r == '"' && !esc { in = !in }
        esc = false
        if r == '#' && !in { return s[:i] }
    }
    return s
}
func parseString(s string) string { return strings.Trim(strings.TrimSpace(s), "\"") }
func parseArray(s string) []string {
    s = strings.TrimSpace(s)
    if strings.HasPrefix(s, "[") && strings.HasSuffix(s, "]") { s = s[1:len(s)-1] }
    if strings.TrimSpace(s) == "" { return nil }
    var out []string
    for _, p := range strings.Split(s, ",") { out = append(out, strings.TrimSpace(p)) }
    return out
}

func collectFiles(args []string, excludes []string) ([]string, error) {
    if len(args) == 0 { return nil, nil }
    seen := map[string]bool{}
    var files []string
    add := func(p string) {
        if seen[p] || excluded(p, excludes) || shouldIgnoreFile(p) { return }
        seen[p] = true; files = append(files, p)
    }
    for _, arg := range args {
        if excluded(arg, excludes) { continue }
        if strings.HasSuffix(arg, "/...") {
            root := strings.TrimSuffix(arg, "/...")
            if root == "" { root = "." }
            info, err := os.Stat(root)
            if err != nil || !info.IsDir() { return nil, packageErr(arg, err) }
            filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
                if err != nil { return nil }
                if d.IsDir() {
                    base := d.Name()
                    if base == ".git" || base == "testdata" || base == "node_modules" { return filepath.SkipDir }
                    if base == "vendor" && !filepath.IsAbs(root) { return filepath.SkipDir }
                    if excluded(path, excludes) { return filepath.SkipDir }
                    return nil
                }
                if strings.HasSuffix(path, ".go") { add(cleanRel(path)) }
                return nil
            })
            continue
        }
        info, err := os.Stat(arg)
        if err != nil { return nil, packageErr(arg, err) }
        if info.IsDir() {
            entries, _ := os.ReadDir(arg)
            for _, e := range entries {
                if e.IsDir() { continue }
                p := filepath.Join(arg, e.Name())
                if strings.HasSuffix(p, ".go") { add(cleanRel(p)) }
            }
        } else {
            add(cleanRel(arg))
        }
    }
    sort.Strings(files)
    return files, nil
}

func packageErr(arg string, err error) error {
    if filepath.IsAbs(arg) {
        return fmt.Errorf("linting - getting packages: getting packages - resolving packages in dots: import %q: cannot import absolute path", arg)
    }
    return fmt.Errorf("linting - getting packages: getting packages - resolving packages in dots: go/build: go list %s: %v", arg, err)
}

func cleanRel(p string) string {
    if filepath.IsAbs(p) { return filepath.Clean(p) }
    c := filepath.Clean(p)
    if strings.HasPrefix(p, "./") && !strings.HasPrefix(c, "./") { c = "./" + c }
    if c == "." { return p }
    return c
}

func shouldIgnoreFile(p string) bool {
    if strings.HasSuffix(p, "_test.go") { return true }
    b, err := os.ReadFile(p)
    if err == nil && isGenerated(b) { return true }
    return false
}
func isGenerated(b []byte) bool {
    head := string(b)
    if len(head) > 4096 { head = head[:4096] }
    return strings.Contains(head, "Code generated") && strings.Contains(head, "DO NOT EDIT")
}
func excluded(path string, patterns []string) bool {
    norm := filepath.ToSlash(filepath.Clean(path))
    noDot := strings.TrimPrefix(norm, "./")
    for _, pat := range patterns {
        pp := filepath.ToSlash(filepath.Clean(pat))
        ppNoDot := strings.TrimPrefix(pp, "./")
        if strings.HasSuffix(pat, "/...") || strings.HasSuffix(pp, "/...") {
            pref := strings.TrimSuffix(ppNoDot, "/...")
            if noDot == pref || strings.HasPrefix(noDot, pref+"/") { return true }
            continue
        }
        if norm == pp || noDot == ppNoDot { return true }
        if ok, _ := filepath.Match(ppNoDot, noDot); ok { return true }
        if ok, _ := filepath.Match(pp, norm); ok { return true }
    }
    return false
}

func lintFiles(paths []string, cfg Config) []Failure {
    parsed := make([]*ParsedFile, 0, len(paths))
    var failures []Failure
    for _, p := range paths {
        pf := parseFile(p)
        parsed = append(parsed, pf)
        if pf.ParseErr != nil {
            pos := token.Position{Filename: p, Line: 1, Column: 1}
            if pf.File != nil && pf.FSet != nil { pos = pf.FSet.Position(pf.File.Package) }
            // parser errors include filename:line:col. Keep revive's "invalid file" prefix.
            if el, ok := pf.ParseErr.(scannerErrList); ok && len(el.Errors()) > 0 { _ = el }
            msg := fmt.Sprintf("invalid file %s: %v", filepath.Base(p), pf.ParseErr)
            // If the parser used the full path in the error, revive still includes it after the prefix.
            failures = append(failures, newFailure("", "", msg, pf.posFromTokenPos(pos), pf.posFromTokenPos(pos), 1))
            continue
        }
    }
    enabled := map[string]bool{}
    for _, r := range cfg.EnabledRules { enabled[r] = true }
    if enabled["line-length-limit"] { failures = append(failures, lintLineLength(parsed, cfg)... ) }
    if enabled["package-comments"] { failures = append(failures, lintPackageComments(parsed)... ) }
    for _, pf := range parsed {
        if pf.File == nil || pf.ParseErr != nil { continue }
        if enabled["blank-imports"] { failures = append(failures, lintBlankImports(pf)... ) }
        if enabled["dot-imports"] { failures = append(failures, lintDotImports(pf)... ) }
        if enabled["exported"] { failures = append(failures, lintExported(pf)... ) }
        if enabled["var-naming"] { failures = append(failures, lintVarNaming(pf)... ) }
        if enabled["error-strings"] { failures = append(failures, lintErrorStrings(pf)... ) }
        if enabled["error-naming"] { failures = append(failures, lintErrorNaming(pf)... ) }
        if enabled["error-return"] { failures = append(failures, lintErrorReturn(pf)... ) }
        if enabled["context-as-argument"] { failures = append(failures, lintContextAsArgument(pf)... ) }
        if enabled["increment-decrement"] { failures = append(failures, lintIncDec(pf)... ) }
        if enabled["var-declaration"] { failures = append(failures, lintVarDecl(pf)... ) }
        if enabled["range"] { failures = append(failures, lintRange(pf)... ) }
        if enabled["receiver-naming"] { failures = append(failures, lintReceiverNaming(pf)... ) }
        if enabled["unexported-return"] { failures = append(failures, lintUnexportedReturn(pf)... ) }
        if enabled["indent-error-flow"] || enabled["superfluous-else"] { failures = append(failures, lintIndentErrorFlow(pf)... ) }
        if enabled["errorf"] { failures = append(failures, lintErrorf(pf)... ) }
        if enabled["empty-block"] { failures = append(failures, lintEmptyBlock(pf)... ) }
        if enabled["unused-parameter"] { failures = append(failures, lintUnusedParam(pf)... ) }
        if enabled["unreachable-code"] { failures = append(failures, lintUnreachable(pf)... ) }
        if enabled["redefines-builtin-id"] { failures = append(failures, lintRedefinesBuiltin(pf)... ) }
        if enabled["if-return"] { failures = append(failures, lintIfReturn(pf)... ) }
    }
    return failures
}

// local interface to avoid importing go/scanner only for a type assertion; not essential.
type scannerErrList interface{ Errors() []error }

func parseFile(p string) *ParsedFile {
    src, err := os.ReadFile(p)
    if err != nil { src = nil }
    fset := token.NewFileSet()
    file, perr := parser.ParseFile(fset, p, src, parser.ParseComments)
    pf := &ParsedFile{Path: p, Src: src, FSet: fset, File: file, ParseErr: perr, LineStart: computeLineStarts(src)}
    pf.Ignored = parseDirectives(pf)
    return pf
}

func computeLineStarts(src []byte) []int {
    starts := []int{0}
    for i, b := range src { if b == '\n' { starts = append(starts, i+1) } }
    return starts
}

func (pf *ParsedFile) pos(pos token.Pos) Pos {
    if !pos.IsValid() { return Pos{Filename: pf.Path} }
    p := pf.FSet.Position(pos)
    return Pos{Filename: p.Filename, Offset: p.Offset, Line: p.Line, Column: p.Column}
}
func (pf *ParsedFile) posFromTokenPos(p token.Position) Pos { return Pos{Filename: p.Filename, Offset: p.Offset, Line: p.Line, Column: p.Column} }
func (pf *ParsedFile) posEnd(pos token.Pos) Pos { return pf.pos(pos) }

func newFailure(rule, cat, msg string, start, end Pos, conf float64) Failure {
    return Failure{Severity: "warning", Failure: msg, RuleName: rule, Category: cat, Position: Span{Start: start, End: end}, Confidence: conf, ReplacementLine: ""}
}
func fail(pf *ParsedFile, rule, msg string, start, end token.Pos, conf float64) Failure {
    return newFailure(rule, ruleCategory[rule], msg, pf.pos(start), pf.pos(end), conf)
}

func parseDirectives(pf *ParsedFile) map[int]map[string]bool {
    ignored := map[int]map[string]bool{}
    if pf.File == nil { return ignored }
    allDisabled := map[string]bool{}
    lineDisabled := map[int]map[string]bool{}
    comments := []*ast.Comment{}
    for _, cg := range pf.File.Comments { comments = append(comments, cg.List...) }
    sort.Slice(comments, func(i,j int) bool { return comments[i].Pos() < comments[j].Pos() })
    for _, c := range comments {
        text := strings.TrimSpace(strings.TrimPrefix(strings.TrimPrefix(c.Text, "//"), "/*"))
        text = strings.TrimSuffix(text, "*/")
        idx := strings.Index(text, "revive:")
        if idx < 0 { continue }
        directive := strings.TrimSpace(text[idx+len("revive:"):])
        line := pf.pos(c.Pos()).Line
        action, rules := parseDirective(directive)
        switch action {
        case "disable":
            if len(rules)==0 { allDisabled["*"] = true } else { for _, r := range rules { allDisabled[r]=true } }
        case "enable":
            if len(rules)==0 { delete(allDisabled,"*"); allDisabled = map[string]bool{} } else { for _, r := range rules { delete(allDisabled,r) } }
        case "disable-next-line":
            if lineDisabled[line+1] == nil { lineDisabled[line+1] = map[string]bool{} }
            if len(rules)==0 { lineDisabled[line+1]["*"] = true } else { for _, r := range rules { lineDisabled[line+1][r]=true } }
        case "disable-line":
            if lineDisabled[line] == nil { lineDisabled[line] = map[string]bool{} }
            if len(rules)==0 { lineDisabled[line]["*"] = true } else { for _, r := range rules { lineDisabled[line][r]=true } }
        }
    }
    // Build a per-line disabled set by replaying comments in source order.
    active := map[string]bool{}
    commentByLine := map[int][]string{}
    for _, c := range comments {
        text := strings.TrimSpace(strings.TrimPrefix(strings.TrimPrefix(c.Text, "//"), "/*"))
        if idx := strings.Index(text, "revive:"); idx >= 0 { commentByLine[pf.pos(c.Pos()).Line] = append(commentByLine[pf.pos(c.Pos()).Line], strings.TrimSpace(text[idx+len("revive:"):])) }
    }
    maxLine := len(pf.LineStart)+1
    for ln:=1; ln<=maxLine; ln++ {
        for _, d := range commentByLine[ln] {
            action, rules := parseDirective(d)
            switch action {
            case "disable":
                if len(rules)==0 { active["*"]=true } else { for _, r := range rules { active[r]=true } }
            case "enable":
                if len(rules)==0 { active=map[string]bool{} } else { for _, r := range rules { delete(active,r) } }
            }
        }
        if len(active)>0 || len(lineDisabled[ln])>0 || len(allDisabled)>0 {
            m := map[string]bool{}
            for k,v := range active { m[k]=v }
            for k,v := range lineDisabled[ln] { m[k]=v }
            ignored[ln]=m
        }
    }
    return ignored
}

func parseDirective(d string) (string, []string) {
    d = strings.TrimSpace(d)
    parts := strings.Split(d, ":")
    action := strings.TrimSpace(parts[0])
    var rules []string
    if len(parts) > 1 {
        for _, r := range strings.Split(parts[1], ",") { if strings.TrimSpace(r)!="" { rules=append(rules, strings.TrimSpace(r)) } }
    }
    return action, rules
}

func applyDirectivesAndConfig(failures *[]Failure, cfg Config) {
    out := (*failures)[:0]
    parsedCache := map[string]*ParsedFile{}
    for _, f := range *failures {
        if cfg.Confidence > 0 && f.Confidence < cfg.Confidence { continue }
        if rc := cfg.RuleConfigs[f.RuleName]; rc != nil && rc.Severity != "" { f.Severity = rc.Severity } else if cfg.Severity != "" { f.Severity = cfg.Severity }
        if f.Severity == "" { f.Severity = "warning" }
        if f.RuleName != "" {
            pf := parsedCache[f.Position.Start.Filename]
            if pf == nil {
                // Directives were already parsed, but this late path is only needed for failures generated with filenames.
                pf = &ParsedFile{Path:f.Position.Start.Filename, Ignored: map[int]map[string]bool{}}
                parsedCache[f.Position.Start.Filename] = pf
            }
        }
        out = append(out, f)
    }
    *failures = out
}

func directiveFilter(failures []Failure, parsed []*ParsedFile) []Failure { return failures }

func ruleDisabledAt(pf *ParsedFile, rule string, line int) bool {
    if pf == nil || pf.Ignored == nil { return false }
    m := pf.Ignored[line]
    return m["*"] || m[rule]
}
func addIfNotDisabled(out *[]Failure, pf *ParsedFile, f Failure) {
    if !ruleDisabledAt(pf, f.RuleName, f.Position.Start.Line) { *out = append(*out, f) }
}

func lintLineLength(files []*ParsedFile, cfg Config) []Failure {
    limit := 0
    if rc := cfg.RuleConfigs["line-length-limit"]; rc != nil && len(rc.Arguments)>0 {
        limit,_ = strconv.Atoi(strings.Trim(rc.Arguments[0], "\""))
    }
    if limit <= 0 { return nil }
    var out []Failure
    for _, pf := range files {
        if pf.ParseErr != nil && len(pf.Src)==0 { continue }
        lines := strings.Split(strings.ReplaceAll(string(pf.Src), "\r\n", "\n"), "\n")
        for i, line := range lines {
            if i == len(lines)-1 && line == "" { continue }
            l := len(line)
            if l > limit {
                start := Pos{Filename: pf.Path, Line: i+1, Column: 0}
                end := Pos{Filename: pf.Path, Line: i+1, Column: l}
                f := newFailure("line-length-limit", ruleCategory["line-length-limit"], fmt.Sprintf("line is %d characters, out of limit %d", l, limit), start, end, 1)
                addIfNotDisabled(&out, pf, f)
            }
        }
    }
    return out
}

func lintPackageComments(files []*ParsedFile) []Failure {
    groups := map[string][]*ParsedFile{}
    for _, pf := range files { if pf.File != nil && pf.ParseErr == nil { key := filepath.Dir(pf.Path)+"\x00"+pf.File.Name.Name; groups[key]=append(groups[key], pf) } }
    var out []Failure
    for _, g := range groups {
        sort.Slice(g, func(i,j int) bool { return g[i].Path < g[j].Path })
        pf := g[0]
        var msg string
        if pf.File.Doc == nil || strings.TrimSpace(pf.File.Doc.Text()) == "" {
            msg = "should have a package comment"
        } else {
            text := strings.TrimSpace(strings.ReplaceAll(pf.File.Doc.Text(), "\n", " "))
            want := "Package " + pf.File.Name.Name
            if !(strings.HasPrefix(text, want+" ") || strings.HasPrefix(text, want+".") || strings.HasPrefix(text, want+",") ) {
                msg = fmt.Sprintf("package comment should be of the form \"Package %s ...\"", pf.File.Name.Name)
            }
        }
        if msg != "" { addIfNotDisabled(&out, pf, fail(pf,"package-comments",msg,pf.File.Package,pf.File.Name.End(),1)) }
    }
    return out
}

func lintBlankImports(pf *ParsedFile) []Failure {
    var out []Failure
    for _, is := range pf.File.Imports {
        if is.Name != nil && is.Name.Name == "_" {
            if pf.File.Name.Name != "main" && !strings.HasSuffix(pf.Path, "_test.go") && is.Doc == nil && is.Comment == nil {
                addIfNotDisabled(&out,pf,fail(pf,"blank-imports","a blank import should be only in a main or test package, or have a comment justifying it",is.Name.Pos(),is.Name.End(),1))
            }
        }
    }
    return out
}
func lintDotImports(pf *ParsedFile) []Failure {
    var out []Failure
    for _, is := range pf.File.Imports {
        if is.Name != nil && is.Name.Name == "." { addIfNotDisabled(&out,pf,fail(pf,"dot-imports","should not use dot imports",is.Name.Pos(),is.Name.End(),1)) }
    }
    return out
}

func lintExported(pf *ParsedFile) []Failure {
    var out []Failure
    for _, decl := range pf.File.Decls {
        switch d := decl.(type) {
        case *ast.GenDecl:
            for _, sp := range d.Specs {
                switch s := sp.(type) {
                case *ast.TypeSpec:
                    if ast.IsExported(s.Name.Name) {
                        doc := s.Doc; if doc == nil { doc = d.Doc }
                        msg := exportedCommentMsg("type", s.Name.Name, "", doc, true)
                        if msg != "" { start := s.Name.Pos(); if doc != nil && badComment(doc, s.Name.Name, true) { start = d.Pos() }; addIfNotDisabled(&out,pf,fail(pf,"exported",msg,start,s.End(),1)) }
                    }
                case *ast.ValueSpec:
                    kind := "var"; if d.Tok == token.CONST { kind = "const" }
                    for _, name := range s.Names {
                        if !ast.IsExported(name.Name) { continue }
                        doc := s.Doc; if doc == nil { doc = d.Doc }
                        msg := exportedCommentMsg(kind, name.Name, "", doc, false)
                        if msg == fmt.Sprintf("exported %s %s should have comment or be unexported", kind, name.Name) && kind=="const" && d.Lparen.IsValid() {
                            msg = fmt.Sprintf("exported const %s should have comment (or a comment on this block) or be unexported", name.Name)
                        }
                        if msg != "" { addIfNotDisabled(&out,pf,fail(pf,"exported",msg,name.Pos(),name.End(),1)) }
                    }
                }
            }
        case *ast.FuncDecl:
            if d.Name == nil || !ast.IsExported(d.Name.Name) { continue }
            kind := "function"
            qual := d.Name.Name
            displayName := d.Name.Name
            if d.Recv != nil && len(d.Recv.List)>0 {
                kind = "method"
                rt := recvTypeName(d.Recv.List[0].Type)
                qual = rt + "." + d.Name.Name
            }
            msg := ""
            if d.Doc == nil || strings.TrimSpace(d.Doc.Text()) == "" {
                if kind == "method" { msg = fmt.Sprintf("exported method %s should have comment or be unexported", qual) } else { msg = fmt.Sprintf("exported function %s should have comment or be unexported", d.Name.Name) }
            } else if badComment(d.Doc, displayName, false) {
                if kind == "method" { msg = fmt.Sprintf("comment on exported method %s should be of the form \"%s ...\"", qual, displayName) } else { msg = fmt.Sprintf("comment on exported function %s should be of the form \"%s ...\"", d.Name.Name, displayName) }
            }
            if msg != "" { addIfNotDisabled(&out,pf,fail(pf,"exported",msg,d.Pos(),d.End(),1)) }
        }
    }
    return out
}

func exportedCommentMsg(kind, name, qual string, doc *ast.CommentGroup, article bool) string {
    if doc == nil || strings.TrimSpace(doc.Text()) == "" { return fmt.Sprintf("exported %s %s should have comment or be unexported", kind, name) }
    if badComment(doc, name, article) { return fmt.Sprintf("comment on exported %s %s should be of the form \"%s ...\"%s", kind, name, name, map[bool]string{true:" (with optional leading article)",false:""}[article]) }
    return ""
}
func badComment(doc *ast.CommentGroup, name string, article bool) bool {
    text := strings.TrimSpace(strings.ReplaceAll(doc.Text(), "\n", " "))
    if strings.HasPrefix(text, name+" ") || strings.HasPrefix(text, name+".") || strings.HasPrefix(text, name+",") { return false }
    if article {
        for _, a := range []string{"A ", "An ", "The "} {
            if strings.HasPrefix(text, a+name+" ") || strings.HasPrefix(text, a+name+".") || strings.HasPrefix(text, a+name+",") { return false }
        }
    }
    return true
}

func lintVarNaming(pf *ParsedFile) []Failure {
    var out []Failure
    check := func(kind string, id *ast.Ident) {
        if id == nil || id.Name == "_" { return }
        want := lintName(id.Name)
        if want != id.Name {
            msg := ""
            if strings.Contains(id.Name, "_") { msg = fmt.Sprintf("don't use underscores in Go names; %s %s should be %s", kind, id.Name, want) } else { msg = fmt.Sprintf("%s %s should be %s", kind, id.Name, want) }
            addIfNotDisabled(&out,pf,fail(pf,"var-naming",msg,id.Pos(),id.End(),0.9))
        }
    }
    for _, decl := range pf.File.Decls {
        switch d := decl.(type) {
        case *ast.GenDecl:
            for _, sp := range d.Specs {
                switch s := sp.(type) {
                case *ast.TypeSpec: check("type", s.Name)
                case *ast.ValueSpec:
                    kind := "var"; if d.Tok == token.CONST { kind = "const" }
                    for _, n := range s.Names { check(kind, n) }
                }
            }
        case *ast.FuncDecl:
            check("func", d.Name)
            if d.Type.Params != nil { for _, fl := range d.Type.Params.List { for _, n := range fl.Names { check("var", n) } } }
        }
    }
    return out
}

func lintName(name string) string {
    if name == "" || name == "_" { return name }
    leading := strings.HasPrefix(name, "_")
    trailing := strings.HasSuffix(name, "_")
    parts := strings.FieldsFunc(name, func(r rune) bool { return r=='_' })
    if len(parts) == 0 { return name }
    for i,p := range parts {
        parts[i] = fixInitialisms(p)
        if i>0 && parts[i] != "" { parts[i] = strings.ToUpper(parts[i][:1]) + parts[i][1:] }
    }
    res := strings.Join(parts, "")
    if leading { res = "_"+res }
    if trailing { res = res+"_" }
    return res
}
func fixInitialisms(s string) string {
    if s == "" { return s }
    // Split CamelCase-ish words and rewrite recognized initialisms.
    for init := range commonInitialisms {
        re := regexp.MustCompile(`(?i)`+regexp.QuoteMeta(init))
        s = re.ReplaceAllStringFunc(s, func(m string) string {
            if strings.EqualFold(m, init) { return init }
            return m
        })
    }
    // More careful pass for words embedded with normal Go casing.
    words := splitNameWords(s)
    if len(words) <= 1 {
        if commonInitialisms[strings.ToUpper(s)] { return strings.ToUpper(s) }
        return s
    }
    var b strings.Builder
    for _, w := range words {
        up := strings.ToUpper(w)
        if commonInitialisms[up] { b.WriteString(up) } else { b.WriteString(w) }
    }
    return b.String()
}
func splitNameWords(s string) []string {
    if s == "" { return nil }
    var words []string
    start := 0
    r := []rune(s)
    for i:=1; i<len(r); i++ {
        if unicode.IsUpper(r[i]) && (unicode.IsLower(r[i-1]) || (i+1<len(r) && unicode.IsLower(r[i+1]))) {
            words = append(words, string(r[start:i])); start=i
        }
    }
    words = append(words, string(r[start:]))
    return words
}

func lintErrorStrings(pf *ParsedFile) []Failure {
    var out []Failure
    ast.Inspect(pf.File, func(n ast.Node) bool {
        call, ok := n.(*ast.CallExpr); if !ok { return true }
        if !isCall(call.Fun, "errors", "New") && !isCall(call.Fun, "fmt", ".Errorf") { return true }
        if len(call.Args)==0 { return true }
        lit, ok := call.Args[0].(*ast.BasicLit); if !ok || lit.Kind != token.STRING { return true }
        val, err := strconv.Unquote(lit.Value); if err != nil { return true }
        if badErrorString(val) { addIfNotDisabled(&out,pf,fail(pf,"error-strings","error strings should not be capitalized or end with punctuation or a newline",lit.Pos(),lit.End(),0.8)) }
        return true
    })
    return out
}
func badErrorString(s string) bool {
    if s == "" { return false }
    if strings.HasSuffix(s,".") || strings.HasSuffix(s,":") || strings.HasSuffix(s,"!") || strings.HasSuffix(s,"?") || strings.HasSuffix(s,"\n") { return true }
    r, _ := utf8First(s)
    return unicode.IsUpper(r)
}
func utf8First(s string) (rune,int) { for i,r := range s { return r,i }; return 0,0 }

func lintErrorNaming(pf *ParsedFile) []Failure {
    var out []Failure
    for _, decl := range pf.File.Decls {
        gd, ok := decl.(*ast.GenDecl); if !ok || gd.Tok != token.VAR { continue }
        for _, sp := range gd.Specs {
            vs := sp.(*ast.ValueSpec)
            for i,n := range vs.Names {
                if !strings.HasSuffix(n.Name, "Error") { continue }
                isErr := false
                if i < len(vs.Values) { if call, ok := vs.Values[i].(*ast.CallExpr); ok && isCall(call.Fun,"errors","New") { isErr=true } }
                if !isErr { continue }
                base := strings.TrimSuffix(n.Name, "Error")
                want := "err" + strings.ToUpper(base[:1]) + base[1:]
                if ast.IsExported(n.Name) { want = "Err" + base }
                addIfNotDisabled(&out,pf,fail(pf,"error-naming",fmt.Sprintf("error var %s should have name of the form %s", n.Name, want),n.Pos(),n.End(),0.8))
            }
        }
    }
    return out
}

func lintErrorReturn(pf *ParsedFile) []Failure {
    var out []Failure
    for _, decl := range pf.File.Decls {
        fd, ok := decl.(*ast.FuncDecl); if !ok || fd.Type.Results == nil { continue }
        var types []ast.Expr
        for _, fl := range fd.Type.Results.List {
            count := len(fl.Names); if count==0 { count=1 }
            for i:=0;i<count;i++ { types=append(types, fl.Type) }
        }
        if len(types) <= 1 { continue }
        for i,t := range types[:len(types)-1] {
            if isErrorType(t) && !isErrorType(types[len(types)-1]) { _ = i }
            if isErrorType(t) { addIfNotDisabled(&out,pf,fail(pf,"error-return","error should be the last type when returning multiple items",fd.Pos(),fd.Name.End(),1)); break }
        }
    }
    return out
}
func isErrorType(e ast.Expr) bool { id,ok:=e.(*ast.Ident); return ok && id.Name=="error" }

func lintContextAsArgument(pf *ParsedFile) []Failure {
    var out []Failure
    for _, decl := range pf.File.Decls {
        fd, ok := decl.(*ast.FuncDecl); if !ok || fd.Type.Params == nil { continue }
        paramIndex := 0
        for _, fl := range fd.Type.Params.List {
            names := fl.Names; if len(names)==0 { names=[]*ast.Ident{{Name:"", NamePos:fl.Type.Pos()}} }
            for _, name := range names {
                if isContextType(fl.Type) && paramIndex != 0 { addIfNotDisabled(&out,pf,fail(pf,"context-as-argument","context.Context should be the first parameter of a function",name.Pos(),name.End(),1)) }
                paramIndex++
            }
        }
    }
    return out
}
func isContextType(e ast.Expr) bool { se,ok:=e.(*ast.SelectorExpr); if !ok || se.Sel.Name!="Context" { return false }; id,ok:=se.X.(*ast.Ident); return ok && id.Name=="context" }

func lintIncDec(pf *ParsedFile) []Failure {
    var out []Failure
    ast.Inspect(pf.File, func(n ast.Node) bool {
        as, ok := n.(*ast.AssignStmt); if !ok || len(as.Lhs)!=1 || len(as.Rhs)!=1 { return true }
        if as.Tok != token.ADD_ASSIGN && as.Tok != token.SUB_ASSIGN { return true }
        lit, ok := as.Rhs[0].(*ast.BasicLit); if !ok || lit.Value!="1" { return true }
        lhs := exprString(as.Lhs[0])
        op := "++"; tok := "+="; if as.Tok==token.SUB_ASSIGN { op="--"; tok="-=" }
        addIfNotDisabled(&out,pf,fail(pf,"increment-decrement",fmt.Sprintf("should replace %s %s 1 with %s%s", lhs, tok, lhs, op),as.Pos(),as.End(),0.8))
        return true
    })
    return out
}

func lintVarDecl(pf *ParsedFile) []Failure {
    var out []Failure
    for _, decl := range pf.File.Decls {
        gd, ok := decl.(*ast.GenDecl); if !ok || gd.Tok != token.VAR { continue }
        for _, sp := range gd.Specs {
            vs := sp.(*ast.ValueSpec)
            if vs.Type == nil || len(vs.Names)!=1 || len(vs.Values)!=1 { continue }
            name := vs.Names[0].Name
            typ := exprString(vs.Type)
            val := exprString(vs.Values[0])
            if isZeroValue(typ, vs.Values[0]) && typ != "bool" {
                msg := fmt.Sprintf("should drop = %s from declaration of var %s; it is the zero value", val, name)
                addIfNotDisabled(&out,pf,fail(pf,"var-declaration",msg,vs.Values[0].Pos(),vs.Values[0].End(),1))
            } else {
                msg := fmt.Sprintf("should omit type %s from declaration of var %s; it will be inferred from the right-hand side", typ, name)
                addIfNotDisabled(&out,pf,fail(pf,"var-declaration",msg,vs.Type.Pos(),vs.Type.End(),1))
            }
        }
    }
    return out
}
func isZeroValue(typ string, e ast.Expr) bool {
    switch v := e.(type) {
    case *ast.BasicLit:
        if typ=="string" && v.Value=="\"\"" { return true }
        if (strings.HasPrefix(typ,"int") || strings.HasPrefix(typ,"uint")) && v.Value=="0" { return true }
        if (strings.HasPrefix(typ,"float") || typ=="float64" || typ=="float32") && (v.Value=="0.0" || v.Value=="0") { return true }
    case *ast.Ident:
        if v.Name=="nil" { return true }
        if typ!="bool" && v.Name=="false" { return true }
    }
    return false
}

func lintRange(pf *ParsedFile) []Failure {
    var out []Failure
    ast.Inspect(pf.File, func(n ast.Node) bool {
        rs, ok := n.(*ast.RangeStmt); if !ok { return true }
        if id, ok := rs.Value.(*ast.Ident); ok && id.Name=="_" {
            key := exprString(rs.Key)
            tok := ":="; if rs.Tok == token.ASSIGN { tok = "=" }
            msg := fmt.Sprintf("should omit 2nd value from range; this loop is equivalent to `for %s %s range ...`", key, tok)
            addIfNotDisabled(&out,pf,fail(pf,"range",msg,id.Pos(),id.End(),1))
        }
        return true
    })
    return out
}

func lintReceiverNaming(pf *ParsedFile) []Failure {
    var out []Failure
    first := map[string]string{}
    for _, decl := range pf.File.Decls {
        fd, ok := decl.(*ast.FuncDecl); if !ok || fd.Recv == nil || len(fd.Recv.List)==0 { continue }
        fl := fd.Recv.List[0]
        if len(fl.Names)==0 { continue }
        name := fl.Names[0].Name
        typ := recvTypeName(fl.Type)
        msg := ""
        switch name {
        case "this", "self": msg = "receiver name should be a reflection of its identity; don't use generic names such as \"this\" or \"self\""
        case "_": msg = "receiver name should not be an underscore, omit the name if it is unused"
        default:
            if prev, ok := first[typ]; ok && prev != name { msg = fmt.Sprintf("receiver name %s should be consistent with previous receiver name %s for %s", name, prev, typ) } else if !ok { first[typ]=name }
        }
        if msg != "" { addIfNotDisabled(&out,pf,fail(pf,"receiver-naming",msg,fd.Pos(),fd.Name.End(),1)) }
    }
    return out
}

func lintUnexportedReturn(pf *ParsedFile) []Failure {
    var out []Failure
    for _, decl := range pf.File.Decls {
        fd, ok := decl.(*ast.FuncDecl); if !ok || fd.Type.Results == nil || !ast.IsExported(fd.Name.Name) { continue }
        for _, fl := range fd.Type.Results.List {
            name := typeName(fl.Type)
            if name != "" && !ast.IsExported(name) && name != "error" && !isBuiltinType(name) {
                msg := fmt.Sprintf("exported func %s returns unexported type %s.%s, which can be annoying to use", fd.Name.Name, pf.File.Name.Name, name)
                addIfNotDisabled(&out,pf,fail(pf,"unexported-return",msg,fl.Type.Pos(),fl.Type.End(),0.8))
            }
        }
    }
    return out
}
func typeName(e ast.Expr) string { switch t:=e.(type) { case *ast.Ident: return t.Name; case *ast.StarExpr: return typeName(t.X); case *ast.ArrayType: return ""; case *ast.SelectorExpr: return "" }; return "" }
func isBuiltinType(s string) bool { return builtinKinds[s]=="type" }

func lintIndentErrorFlow(pf *ParsedFile) []Failure {
    var out []Failure
    ast.Inspect(pf.File, func(n ast.Node) bool {
        ifs, ok := n.(*ast.IfStmt); if !ok { return true }
        if ifs.Else == nil { return true }
        if _, nested := ifs.Else.(*ast.IfStmt); nested { return true }
        if !blockEndsWithBranch(ifs.Body) { return true }
        bs, ok := ifs.Else.(*ast.BlockStmt); if !ok { return true }
        msg := "if block ends with a return statement, so drop this else and outdent its block"
        addIfNotDisabled(&out,pf,fail(pf,"indent-error-flow",msg,bs.Lbrace,bs.Rbrace+1,1))
        return true
    })
    return out
}
func blockEndsWithBranch(b *ast.BlockStmt) bool {
    if b == nil || len(b.List)==0 { return false }
    switch b.List[len(b.List)-1].(type) { case *ast.ReturnStmt, *ast.BranchStmt: return true }
    return false
}

func lintErrorf(pf *ParsedFile) []Failure {
    var out []Failure
    ast.Inspect(pf.File, func(n ast.Node) bool {
        call, ok := n.(*ast.CallExpr); if !ok || !isCall(call.Fun,"errors","New") || len(call.Args)!=1 { return true }
        inner, ok := call.Args[0].(*ast.CallExpr); if ok && isCall(inner.Fun,"fmt","Sprintf") { addIfNotDisabled(&out,pf,fail(pf,"errorf","should replace errors.New(fmt.Sprintf(...)) with fmt.Errorf(...)",call.Pos(),call.End(),0.8)) }
        return true
    })
    return out
}

func lintEmptyBlock(pf *ParsedFile) []Failure {
    var out []Failure
    ast.Inspect(pf.File, func(n ast.Node) bool {
        switch x := n.(type) {
        case *ast.BlockStmt:
            if len(x.List) != 0 { return true }
            // Ignore function bodies; flag control-flow blocks.
            return true
        case *ast.IfStmt:
            if x.Body != nil && len(x.Body.List)==0 { addIfNotDisabled(&out,pf,fail(pf,"empty-block","this block is empty, you can remove it",x.Pos(),x.End(),1)) }
        case *ast.ForStmt:
            if x.Body != nil && len(x.Body.List)==0 { addIfNotDisabled(&out,pf,fail(pf,"empty-block","this block is empty, you can remove it",x.Pos(),x.End(),1)) }
        case *ast.RangeStmt:
            if x.Body != nil && len(x.Body.List)==0 { addIfNotDisabled(&out,pf,fail(pf,"empty-block","this block is empty, you can remove it",x.Pos(),x.End(),1)) }
        case *ast.SwitchStmt:
            if x.Body != nil && len(x.Body.List)==0 { addIfNotDisabled(&out,pf,fail(pf,"empty-block","this block is empty, you can remove it",x.Pos(),x.End(),1)) }
        }
        return true
    })
    return out
}

func lintUnusedParam(pf *ParsedFile) []Failure {
    var out []Failure
    for _, decl := range pf.File.Decls {
        fd, ok := decl.(*ast.FuncDecl); if !ok || fd.Body == nil || fd.Type.Params == nil { continue }
        counts := map[string]int{}
        ast.Inspect(fd.Body, func(n ast.Node) bool { if id,ok:=n.(*ast.Ident); ok { counts[id.Name]++ }; return true })
        for _, fl := range fd.Type.Params.List {
            for _, n := range fl.Names {
                if n.Name=="_" { continue }
                if counts[n.Name]==0 { addIfNotDisabled(&out,pf,fail(pf,"unused-parameter",fmt.Sprintf("parameter '%s' seems to be unused, consider removing or renaming it as _", n.Name),n.Pos(),n.End(),0.8)) }
            }
        }
    }
    return out
}

func lintUnreachable(pf *ParsedFile) []Failure {
    var out []Failure
    ast.Inspect(pf.File, func(n ast.Node) bool {
        b, ok := n.(*ast.BlockStmt); if !ok { return true }
        for i, st := range b.List {
            if i < len(b.List)-1 && isTerminating(st) { addIfNotDisabled(&out,pf,fail(pf,"unreachable-code","unreachable code after this statement",st.Pos(),st.End(),1)); break }
        }
        return true
    })
    return out
}
func isTerminating(s ast.Stmt) bool { switch s.(type) { case *ast.ReturnStmt, *ast.BranchStmt: return true }; if e,ok:=s.(*ast.ExprStmt); ok { if c,ok:=e.X.(*ast.CallExpr); ok { if id,ok:=c.Fun.(*ast.Ident); ok && id.Name=="panic" { return true } } }; return false }

func lintRedefinesBuiltin(pf *ParsedFile) []Failure {
    var out []Failure
    check := func(id *ast.Ident) { if id==nil {return}; if kind:=builtinKinds[id.Name]; kind!="" { addIfNotDisabled(&out,pf,fail(pf,"redefines-builtin-id",fmt.Sprintf("redefinition of the built-in %s %s", kind, id.Name),id.Pos(),id.End(),1)) } }
    for _, decl := range pf.File.Decls {
        switch d:=decl.(type) {
        case *ast.FuncDecl:
            check(d.Name)
            if d.Type.Params != nil { for _, fl := range d.Type.Params.List { for _, n := range fl.Names { check(n) } } }
        case *ast.GenDecl:
            for _, sp := range d.Specs {
                switch s:=sp.(type) { case *ast.TypeSpec: check(s.Name); case *ast.ValueSpec: for _, n := range s.Names { check(n) } }
            }
        }
    }
    ast.Inspect(pf.File, func(n ast.Node) bool {
        switch x:=n.(type) { case *ast.AssignStmt: if x.Tok==token.DEFINE { for _, e := range x.Lhs { if id,ok:=e.(*ast.Ident); ok { check(id) } } } }
        return true
    })
    return out
}

func lintIfReturn(pf *ParsedFile) []Failure {
    var out []Failure
    ast.Inspect(pf.File, func(n ast.Node) bool {
        ifs, ok := n.(*ast.IfStmt); if !ok || ifs.Else != nil || len(ifs.Body.List)!=1 { return true }
        ret, ok := ifs.Body.List[0].(*ast.ReturnStmt); if !ok || len(ret.Results)!=1 { return true }
        // Look for following return is not easy here; keep no-op for most cases.
        return true
    })
    return out
}

func isCall(fun ast.Expr, pkg, name string) bool {
    se, ok := fun.(*ast.SelectorExpr); if !ok || se.Sel.Name != name { return false }
    id, ok := se.X.(*ast.Ident); return ok && id.Name == pkg
}
func exprString(e ast.Expr) string {
    if e == nil { return "" }
    switch x:=e.(type) {
    case *ast.Ident: return x.Name
    case *ast.BasicLit: return x.Value
    case *ast.SelectorExpr: return exprString(x.X)+"."+x.Sel.Name
    case *ast.StarExpr: return "*"+exprString(x.X)
    case *ast.ArrayType: return "[]"+exprString(x.Elt)
    case *ast.CallExpr: return exprString(x.Fun)+"(...)"
    case *ast.IndexExpr: return exprString(x.X)+"[...]"
    }
    return "..."
}
func recvTypeName(e ast.Expr) string { if se,ok:=e.(*ast.StarExpr); ok { return recvTypeName(se.X) }; if id,ok:=e.(*ast.Ident); ok { return id.Name }; if se,ok:=e.(*ast.SelectorExpr); ok { return se.Sel.Name }; return exprString(e) }

func sortFailures(f []Failure) {
    sort.SliceStable(f, func(i,j int) bool {
        a,b:=f[i],f[j]
        if a.Position.Start.Filename != b.Position.Start.Filename { return a.Position.Start.Filename < b.Position.Start.Filename }
        if a.Position.Start.Line != b.Position.Start.Line { return a.Position.Start.Line < b.Position.Start.Line }
        if a.Position.Start.Column != b.Position.Start.Column { return a.Position.Start.Column < b.Position.Start.Column }
        if a.RuleName != b.RuleName { return a.RuleName < b.RuleName }
        return a.Failure < b.Failure
    })
}

func formatFailures(format string, failures []Failure) {
    switch format {
    case "default": formatDefault(failures, false, false)
    case "plain": formatDefault(failures, true, false); if len(failures)>0 { fmt.Println() }
    case "unix": formatDefault(failures, false, true); if len(failures)>0 { fmt.Println() }
    case "json": b,_:=json.Marshal(nilSlice(failures)); os.Stdout.Write(b); fmt.Println()
    case "ndjson": for _, f := range failures { b,_:=json.Marshal(f); os.Stdout.Write(b); fmt.Println() }
    case "checkstyle": formatCheckstyle(failures)
    case "stylish": formatStylish(failures)
    case "friendly": formatFriendly(failures)
    case "sarif": formatSARIF(failures)
    }
}
func nilSlice(f []Failure) interface{} { if len(f)==0 { return []Failure(nil) }; return f }
func formatDefault(failures []Failure, plain bool, unix bool) {
    for _, f := range failures {
        p := f.Position.Start
        loc := ""
        if p.Column == 0 { loc = fmt.Sprintf("%s:%d", p.Filename, p.Line) } else { loc = fmt.Sprintf("%s:%d:%d", p.Filename, p.Line, p.Column) }
        if unix { fmt.Printf("%s: [%s] %s\n", loc, f.RuleName, f.Failure) } else if plain { fmt.Printf("%s: %s https://revive.run/r#%s\n", loc, f.Failure, f.RuleName) } else { fmt.Printf("%s: %s\n", loc, f.Failure) }
    }
}

type checkstyle struct { XMLName xml.Name `xml:"checkstyle"`; Version string `xml:"version,attr"`; Files []csFile `xml:"file"` }
type csFile struct { Name string `xml:"name,attr"`; Errors []csErr `xml:"error"` }
type csErr struct { Line int `xml:"line,attr"`; Column int `xml:"column,attr"`; Message string `xml:"message,attr"`; Severity string `xml:"severity,attr"`; Source string `xml:"source,attr"` }
func formatCheckstyle(failures []Failure) {
    fmt.Println("<?xml version='1.0' encoding='UTF-8'?>")
    fmt.Println("<checkstyle version=\"5.0\">")
    by := map[string][]Failure{}
    var names []string
    for _, f := range failures { if by[f.Position.Start.Filename]==nil { names=append(names,f.Position.Start.Filename) }; by[f.Position.Start.Filename]=append(by[f.Position.Start.Filename], f) }
    sort.Strings(names)
    for _, name := range names {
        fmt.Printf("    <file name=\"%s\">\n", xmlEscape(name))
        for _, f := range by[name] {
            fmt.Printf("      <error line=\"%d\" column=\"%d\" message=\"%s (confidence %s)\" severity=\"%s\" source=\"revive/%s\"/>\n", f.Position.Start.Line, f.Position.Start.Column, xmlEscape(f.Failure), confString(f.Confidence), f.Severity, f.RuleName)
        }
        fmt.Println("    </file>")
    }
    fmt.Println("</checkstyle>")
}
func xmlEscape(s string) string { var b bytes.Buffer; xml.EscapeText(&b, []byte(s)); return b.String() }
func confString(f float64) string { if f == float64(int(f)) { return fmt.Sprintf("%d", int(f)) }; return strconv.FormatFloat(f,'f',-1,64) }
func formatStylish(failures []Failure) {
    if len(failures)==0 { return }
    by:=map[string][]Failure{}; var names []string
    for _, f:= range failures { if by[f.Position.Start.Filename]==nil { names=append(names,f.Position.Start.Filename) }; by[f.Position.Start.Filename]=append(by[f.Position.Start.Filename], f) }
    sort.Strings(names)
    for _, name:= range names { fmt.Println(name); for _, f:= range by[name] { fmt.Printf("  (%d, %d)  https://revive.run/r#%-20s %s\n", f.Position.Start.Line, f.Position.Start.Column, f.RuleName, f.Failure) }; fmt.Println() }
    errs,warns:=countSev(failures); fmt.Printf("\n ✖ %d problems (%d errors) (%d warnings)\n", len(failures), errs, warns)
}
func formatFriendly(failures []Failure) {
    if len(failures)==0 { return }
    for _, f:= range failures { icon:="⚠"; if f.Severity=="error" { icon="✖" }; fmt.Printf("  %s  https://revive.run/r#%s  %s\n  %s:%d:%d\n\n", icon, f.RuleName, f.Failure, f.Position.Start.Filename, f.Position.Start.Line, f.Position.Start.Column) }
    errs,warns:=countSev(failures); fmt.Printf("%s %d problems (%d errors, %d warnings)\n\n", "⚠", len(failures), errs, warns)
    counts:=map[string]int{}; for _, f:= range failures { counts[f.RuleName]++ }
    var rules []string; for r:= range counts { rules=append(rules,r) }; sort.Slice(rules, func(i,j int) bool { if counts[rules[i]]==counts[rules[j]] {return rules[i]<rules[j]}; return counts[rules[i]]>counts[rules[j]] })
    if errs>0 { fmt.Println("Errors:") } else { fmt.Println("Warnings:") }
    for _, r:= range rules { fmt.Printf("  %d  %s\n", counts[r], r) }
    fmt.Println()
}
func countSev(f []Failure) (int,int) { e,w:=0,0; for _, x:=range f { if x.Severity=="error" {e++} else {w++} }; return e,w }
func formatSARIF(failures []Failure) {
    type loc struct { PhysicalLocation map[string]interface{} `json:"physicalLocation"` }
    type res struct { Level string `json:"level"`; Locations []loc `json:"locations"`; Message map[string]string `json:"message"`; RuleID string `json:"ruleId"` }
    results:=[]res{}
    for _, f:= range failures { results=append(results,res{Level:f.Severity, RuleID:f.RuleName, Message:map[string]string{"text":f.Failure}, Locations:[]loc{{PhysicalLocation:map[string]interface{}{"artifactLocation":map[string]string{"uri":f.Position.Start.Filename},"region":map[string]int{"startLine":f.Position.Start.Line,"startColumn":f.Position.Start.Column}}}}}) }
    obj:=map[string]interface{}{"version":"2.1.0","runs":[]interface{}{map[string]interface{}{"tool":map[string]interface{}{"driver":map[string]interface{}{"name":"revive","informationUri":"https://revive.run","rules":[]interface{}{map[string]interface{}{"id":"range","helpUri":"https://revive.run/r#range","properties":map[string]string{"severity":"warning"}}}}}}}}
    if len(results)>0 { obj["runs"].([]interface{})[0].(map[string]interface{})["results"] = results }
    b,_:=json.MarshalIndent(obj,"","  "); os.Stdout.Write(b); fmt.Println()
}
